#!/bin/bash
set -eo pipefail
test "$(id -un)" = sunyiq
TASK_PY='/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python'
test -x "$TASK_PY"
printf 'QUERY_UTC=%s
' "$(date -u +%FT%TZ)"
printf 'QUERY_ID=US_INPUT_PROVENANCE_CONTINUATION_20261009_001
NEW_COMPUTE_JOBS=0
'
provenance_rc=0
if provenance=$(timeout --signal=KILL 10 "$TASK_PY" -I -B -X utf8 -c "import base64;exec(base64.b64decode(''))"); then
  :
else
  provenance_rc=$?
fi
printf 'PROVENANCE_EXIT=%s
PROVENANCE_SHA256=' "$provenance_rc"
printf '%s' "$provenance" | sha256sum | cut -d ' ' -f 1
printf 'PROVENANCE_GZIP_BEGIN
'
printf '%s' "$provenance" | gzip -n -c | base64 -w 76
printf 'PROVENANCE_GZIP_END
'
accounting_rc=0
if accounting=$(timeout --signal=KILL 10 sacct -n -P -j 237173 --starttime=2026-10-07 --format=JobID,State,ExitCode,ElapsedRaw,AllocCPUS,MaxRSS,NodeList | head -c 3001); then
  :
else
  accounting_rc=$?
fi
printf 'ACCOUNTING_EXIT=%s
ACCOUNTING_BEGIN
%s
ACCOUNTING_END
' "$accounting_rc" "$accounting"
test "${#accounting}" -le 3000 || exit 1
profile_rc=0
if profile=$(timeout --signal=KILL 15 "$TASK_PY" -I -B -X utf8 -c "import base64;exec(base64.b64decode(''))"); then
  :
else
  profile_rc=$?
fi
printf 'PROFILE_EXIT=%s
PROFILE_SHA256=' "$profile_rc"
printf '%s' "$profile" | sha256sum | cut -d ' ' -f 1
printf 'PROFILE_GZIP_BEGIN
'
printf '%s' "$profile" | gzip -n -c | base64 -w 76
printf 'PROFILE_GZIP_END
'
printf 'READ_ONLY_QUERY_END
'
test "$provenance_rc" -eq 0
test "$accounting_rc" -eq 0
test "$profile_rc" -eq 0
